console.log('t after steps:', s.t);
console.log('angle at t:', s.poly.angle, 'expected', 2*Math.PI*s.t/7);

// invariants
function checkInvariants(st, tag){
  const {poly, balls} = st;
  const R = poly.radius, r = 14;
  let badWall = 0, badPair = 0;
  // signed distance inside polygon: min over edges
  const vs = [];
  for (let i=0;i<9;i++){ const a = poly.angle + 2*Math.PI*i/9; vs.push([poly.cx + R*Math.cos(a), poly.cy + R*Math.sin(a)]); }
  for (const b of balls){
    let best = Infinity;
    for (let e=0;e<9;e++){
      const A = vs[e], Bv = vs[(e+1)%9];
      let nx = -(Bv[1]-A[1]), ny = Bv[0]-A[0];
      const len = Math.hypot(nx,ny); nx/=len; ny/=len;
      if ((poly.cx-A[0])*nx + (poly.cy-A[1])*ny < 0){ nx=-nx; ny=-ny; }
      const d = (b.x-A[0])*nx + (b.y-A[1])*ny;
      best = Math.min(best,d);
    }
    if (best < r - 0.5) badWall++;
  }
  for (let i=0;i<balls.length;i++) for (let j=i+1;j<balls.length;j++){
    const d = Math.hypot(balls[i].x-balls[j].x, balls[i].y-balls[j].y);
    if (d < 28 - 0.5) badPair++;
  }
  const spd = Math.max(...balls.map(b=>Math.hypot(b.vx,b.vy)));
  console.log(tag, 'wallViolations=', badWall, 'pairViolations=', badPair, 'maxSpeed=', spd.toFixed(1));
  if (!isFinite(spd) || balls.some(b=>!isFinite(b.x)||!isFinite(b.y))) { console.log('NaN detected!'); process.exit(1);}
}
